/* Bilingual content field: B(english, russian). Views resolve it via loc()
   from i18n.js — a plain string falls through unchanged, so untranslated
   fields (lesson bodies, exercise prompts) keep working. */
const B = (en, ru) => ({ en, ru });

// Corrupted or unavailable localStorage must never kill the whole app.
function safeJSON(key, fallback) {
  try {
    const v = JSON.parse(localStorage.getItem(key));
    return (v && typeof v === "object") ? v : fallback;
  } catch { return fallback; }
}

